// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;

    function setUp() public {
        c = new RoundFactory();
        c.initialize(); // test contract becomes owner
    }

    function testFuzz_property(address newImpl) public {
        // any address is admissible; the call only succeeds for nonzero values
        bool ok;
        vm.prank(address(this));
        try c.updateRoundImplementation(payable(newImpl)) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: whenever the update succeeds, the stored roundImplementation
        // equals the requested address. (If it reverted, the getter is unchanged.)
        assertTrue(!ok || c.roundImplementation() == newImpl);
    }
}
